using System;
using System.Linq;
using System.Reflection;
using UnityEngine;
namespace BWVR.Editor {
public static class StormChapterChecks {
 static readonly BindingFlags Flags=BindingFlags.Instance|BindingFlags.NonPublic;
 static void Require(bool ok,string why){if(!ok)throw new Exception(why);}
 public static void VerifyModel(){var old=JsonUtility.FromJson<SliceState>("{}");Require(old.Valid()&&old.StormChapter.phase==StormPhase.Dormant,"Historical season started a chapter");var chapter=new StormChapterState{phase=StormPhase.Calm,episode=1};chapter.Step(1,true);Require(chapter.elapsed==0,"Pause advanced chapter");foreach(var expected in new[]{StormPhase.Warning,StormPhase.Storm,StormPhase.Recovery,StormPhase.Complete}){chapter.elapsed=StormChapterState.Duration(chapter.phase)-.05f;chapter.Step(.1f,false);Require(chapter.phase==expected&&chapter.Valid(),"Chapter transition invalid");}Require(!chapter.Resolve(RescueSource.Creature),"Invented assistance accepted");chapter.opportunity=true;chapter.villager=0;Require(chapter.Resolve(RescueSource.Player)&&!chapter.Resolve(RescueSource.Creature)&&chapter.source==RescueSource.Player,"Duplicate / misattributed rescue");var saved=JsonUtility.FromJson<StormChapterState>(JsonUtility.ToJson(chapter));Require(saved.Valid()&&saved.source==RescueSource.Player,"Chapter outcome did not round-trip");saved.actorPoint.x=float.NaN;Require(!saved.Valid(),"Invalid saved actor position accepted");Debug.Log("BWVR_STORM_MODEL_PASS: legacy opt-in, bounded phases, pause, attribution and save validation");}
 public static void Verify(Action<StormChapter> capture=null){
  Require(Application.isPlaying,"Enter Play mode");var slice=UnityEngine.Object.FindAnyObjectByType<QuestSlice>();slice.SetSanctuaryOpen(false);var chapter=slice.Chapter;var god=slice.GetComponentInChildren<CreatureHybrid>();var mind=god.GetComponent<CreatureCuriosity>();var nav=god.GetComponent<IslandNavigator>().world;Require(!nav.TreeNavigationPending,"Wait for navigation updates");var ball=slice.GetComponentInChildren<BeachBall>();var weather=slice.GetComponentInChildren<IslandWeather>();bool automatic=weather.automatic;var people=slice.GetComponentsInChildren<VillagerSocial>();var positions=people.Select(p=>p.transform.position).ToArray();var rotations=people.Select(p=>p.transform.rotation).ToArray();var gp=god.transform.position;var gr=god.transform.rotation;var stateField=typeof(QuestSlice).GetField("state",Flags);var original=(SliceState)stateField.GetValue(slice);var held=(CarryItem[])typeof(QuestSlice).GetField("held",Flags).GetValue(slice);Require(held.All(i=>i==null),"Release objects before QA");var ideas=slice.GetComponentsInChildren<ConstructionInspiration>();var active=ideas.Select(i=>i.gameObject.activeSelf).ToArray();var cooldowns=god.Targets.Where(t=>t.affordance!=null).ToDictionary(t=>t.affordance,t=>t.affordance.cooldown);SliceState test=null;
  void Stage(){god.Interrupt("Storm QA stage");test=new SliceState{developmentFocus=true,observeWithoutFoodWork=true,water=100,crops=100,hunger=.05f};stateField.SetValue(slice,test);chapter.Advance(0,false);god.NewSeason();ball.ResetWorld();foreach(var idea in ideas)idea.gameObject.SetActive(false);foreach(var p in people){p.GetComponent<VillagerResourceGathering>().Cancel();p.GetComponent<VillagerExploration>().ResetTask();p.GetComponent<VillagerBlockPlay>().ResetTask();p.ResetTask();slice.GetComponentInChildren<VillageFamilies>()?.Release(p.GetComponent<VillagerRoutine>());slice.GetComponentInChildren<VillageCathedral>()?.Cancel(p.GetComponent<VillagerRoutine>());p.GetComponent<CarryItem>().held=false;p.Memory.injury=0;p.Memory.trust=.6f;p.transform.position+=Vector3.right*nav.Scale*300;}Require(nav.Sample(ball.Bowling.Start,nav.creature,4,out var foot),"No creature start");god.transform.position=nav.ProjectFoot(foot,nav.creature);var person=people[0];bool visible=false;for(int k=0;k<24&&!visible;k++){var wanted=god.transform.position+Quaternion.Euler(0,k*15,0)*ball.Bowling.Right*nav.Scale*12;if(!person.GetComponent<IslandNavigator>().CanPlace(wanted,out var at))continue;person.transform.position=at;god.transform.LookAt(new Vector3(at.x,god.transform.position.y,at.z));Physics.SyncTransforms();visible=god.CanSeeCue(person.GetComponent<HybridTarget>(),false,true);}Require(visible,"No visible villager start");god.GetComponent<IslandNavigator>().ResetRoute();foreach(var a in cooldowns.Keys)a.cooldown=100000;person.GetComponent<CreatureAffordance>().cooldown=0;var palette=slice.GetComponentInChildren<GodToolPalette>();palette.Cancel();palette.Process(new Ray(Camera.main.transform.position,Camera.main.transform.forward),false,true,false,.1f,false);Physics.SyncTransforms();}
  void Tick(float dt,bool ai){if(!test.paused)test.Hybrid.time+=dt;chapter.Advance(dt,test.paused);if(!test.paused){foreach(var p in people)chapter.TickVillager(p.GetComponent<VillagerRoutine>(),dt);if(ai)god.Tick(dt,false);weather.Advance(dt,false);}}
  void Storm(){slice.SetSanctuaryOpen(true);var home=(GameObject)typeof(QuestSlice).GetField("sanctuaryHome",Flags).GetValue(slice);home.transform.Find("Settings").GetComponent<SpatialTarget>().Activate();var options=(GameObject)typeof(QuestSlice).GetField("sanctuaryOptions",Flags).GetValue(slice);options.transform.Find("Gathering Storm").GetComponent<SpatialTarget>().Activate();Require(!slice.MenuOpen&&chapter.State.Active&&!chapter.Start(),"Sanctuary chapter entry did not start once");slice.GetComponentInChildren<GodToolPalette>().Process(new Ray(Camera.main.transform.position,Camera.main.transform.forward),false,true,false,.1f,false);Require(chapter.State.phase==StormPhase.Calm&&!weather.automatic,"Calm did not own weather");chapter.State.elapsed=StormChapterState.Duration(StormPhase.Calm)-.05f;Tick(.1f,false);Require(chapter.State.phase==StormPhase.Warning&&weather.State.kind==IslandWeatherKind.Wind,"Warning did not use wind");chapter.State.elapsed=StormChapterState.Duration(StormPhase.Warning)-.05f;Tick(.1f,false);Require(chapter.State.phase==StormPhase.Storm&&chapter.Pending&&chapter.Person==people[0]&&weather.State.kind==IslandWeatherKind.Rain,"Storm assistance did not open");}
  void PlayerRescue(bool deferred=false){var item=chapter.Person.GetComponent<CarryItem>();Require((bool)typeof(QuestSlice).GetMethod("TryGrab",Flags).Invoke(slice,new object[]{1,item}),"Native villager pickup failed: paused="+test.paused+" held="+item.held+" grab="+item.CanGrab+" menu="+slice.MenuOpen+" tools="+slice.GetComponentInChildren<GodToolPalette>().ClaimsInput);typeof(QuestSlice).GetMethod("Release",Flags).Invoke(slice,new object[]{1,new Ray(chapter.Refuge+Vector3.up*nav.Scale*30,Vector3.down)});Require((deferred?!chapter.State.resolved&&chapter.State.playerArrivalPending:chapter.State.resolved&&chapter.State.source==RescueSource.Player)&&held[1]==null&&!item.held,"Native player placement was not credited correctly");}
  try{
   Stage();Storm();test.paused=true;var before=JsonUtility.ToJson(chapter.State);Tick(1,true);Require(JsonUtility.ToJson(chapter.State)==before,"Pause advanced chapter/evacuation");test.paused=false;Require(god.Guide(GuidanceIntent.Help,chapter.Person.GetComponent<HybridTarget>()),"Contextual help cue rejected");god.Perceive();var offers=(System.Collections.Generic.List<CreatureCandidate>)typeof(CreatureHybrid).GetField("candidates",Flags).GetValue(god);Require(!offers.Any(c=>c.action==CreatureAction.WaterDelivery&&c.feasible),"Storm help was mistaken for a water job");Require(offers.Any(c=>c.target==chapter.Person.GetComponent<HybridTarget>().id&&c.action==CreatureAction.SocialInteraction&&c.feasible),"No actual rescue offered: visible="+god.CanSeeCue(chapter.Person.GetComponent<HybridTarget>(),false,true)+" pending="+chapter.Pending+" trust="+chapter.Person.Memory.trust);Require(!offers.Any(c=>c.target==chapter.Person.GetComponent<HybridTarget>().id&&c.action==CreatureAction.RespondToGuidance),"A generic visit competed with requested storm assistance");bool carried=false,selected=false;for(int i=0;i<2400&&!chapter.State.resolved;i++){Tick(.05f,true);selected|=mind.Current==CreatureCuriosity.Phase.StormRescue;carried|=chapter.Person.GetComponent<CarryItem>().held;if(carried&&capture!=null&&chapter.State.distress>6){capture(chapter);capture=null;}}Require(selected&&carried&&chapter.State.resolved&&chapter.State.source==RescueSource.Creature,"Creature did not complete rescue: "+mind.Current+" "+god.Explanation+" source="+chapter.State.source);Require(test.Hybrid.receipt.eligible&&test.Hybrid.receipt.action==CreatureAction.SocialInteraction&&test.Hybrid.receipt.target==chapter.Person.GetComponent<HybridTarget>().id,"Rescue lacks contextual social lesson");float trust=chapter.Person.Memory.trust;Require(!chapter.Confirm(RescueSource.Creature)&&chapter.Person.Memory.trust==trust&&god.Feedback(true)&&!god.Feedback(true),"Rescue credit/feedback duplicated");Require(JsonUtility.FromJson<SliceState>(JsonUtility.ToJson(test)).Valid(),"Rescue save rejected");
   chapter.State.elapsed=StormChapterState.Duration(StormPhase.Storm)-.05f;Tick(.1f,false);Require(chapter.State.phase==StormPhase.Recovery&&weather.State.kind==IslandWeatherKind.Clear,"Recovery did not clear weather");chapter.State.elapsed=StormChapterState.Duration(StormPhase.Recovery)-.05f;Tick(.1f,false);Require(chapter.State.phase==StormPhase.Complete&&weather.automatic==chapter.State.previousAutomatic,"Chapter did not release weather");
   Stage();Storm();for(int i=0;i<2400&&!chapter.State.resolved;i++)Tick(.05f,false);Require(chapter.State.resolved&&chapter.State.source==RescueSource.Independent&&!test.Hybrid.receipt.eligible,"Unattended villager did not evacuate independently / credited god");
   Stage();Storm();PlayerRescue();Require(!test.Hybrid.receipt.eligible,"Player rescue trained the creature");
   Stage();Storm();test.paused=true;PlayerRescue(true);Require(!test.Hybrid.receipt.eligible,"Paused player placement trained creature");test.paused=false;Tick(.1f,false);Require(chapter.State.resolved&&chapter.State.source==RescueSource.Player,"Deferred placement lost player attribution");
   Stage();Storm();for(int i=0;i<800&&!chapter.Claimed;i++)Tick(.05f,true);Require(chapter.Claimed,"Resume fixture could not acquire rescue");typeof(QuestSlice).GetMethod("Save",Flags).Invoke(slice,null);var saved=JsonUtility.FromJson<SliceState>(System.IO.File.ReadAllText(System.IO.Path.Combine(Application.persistentDataPath,"bwvr-season-v1.json")));Require(saved.Valid(),"Pending chapter save invalid");var location=saved.StormChapter.actorPoint;god.Interrupt("Resume fixture");typeof(QuestSlice).GetMethod("Load",Flags).Invoke(slice,null);test=(SliceState)stateField.GetValue(slice);god.NewSeason();chapter.Advance(.01f,false);Require(chapter.Pending&&!chapter.Claimed&&!chapter.Person.GetComponent<CarryItem>().held&&Vector3.Distance(chapter.Person.transform.position,nav.ToWorld(location))<nav.Scale*2,"Resume retained ownership / lost safe actor point");PlayerRescue();Require(test.StormChapter.source==RescueSource.Player,"Resumed rescue source incorrect");
   Stage();Storm();for(int i=0;i<1200&&!chapter.Person.GetComponent<CarryItem>().held;i++)Tick(.05f,true);Require(chapter.Person.GetComponent<CarryItem>().held,"Stop fixture did not acquire carried actor");test.paused=true;Require(chapter.Stop()&&!chapter.Stop()&&chapter.State.phase==StormPhase.Stopped&&!chapter.Person.GetComponent<CarryItem>().held&&!chapter.Claimed&&!test.Hybrid.receipt.eligible&&weather.automatic==chapter.State.previousAutomatic,"Ending a paused chapter retained carry or granted credit");test.paused=false;
   Debug.Log("BWVR_STORM_PLAY_PASS: chapter/weather phases, pause, utility-selected contextual creature rescue, safe carry/place/teaching, independent evacuation, native player rescue, source isolation and saved pending-rescue recovery");
  }finally{held[0]=held[1]=null;god.Interrupt("Storm QA complete");foreach(var p in people){p.GetComponent<CarryItem>().held=false;p.GetComponent<Collider>().enabled=true;p.GetComponent<VillagerExploration>().ResetTask();}stateField.SetValue(slice,original);chapter.Advance(0,false);weather.automatic=automatic;god.NewSeason();ball.ResetWorld();foreach(var c in cooldowns)c.Key.cooldown=c.Value;for(int i=0;i<ideas.Length;i++)ideas[i].gameObject.SetActive(active[i]);god.transform.SetPositionAndRotation(gp,gr);god.GetComponent<IslandNavigator>().ResetRoute();for(int i=0;i<people.Length;i++){people[i].transform.SetPositionAndRotation(positions[i],rotations[i]);people[i].GetComponent<IslandNavigator>().ResetRoute();}Physics.SyncTransforms();}
 }
}
}
